import { inject, Injectable, PLATFORM_ID } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, BehaviorSubject } from 'rxjs';
import { tap } from 'rxjs/operators';
import { Router } from '@angular/router';
import { isPlatformBrowser } from '@angular/common';

export interface User {
  id: number;
  email: string;
  name: string;
  createdAt: string;
  updatedAt: string;
}

export interface AuthResponse {
  token: string;
  user: User;
}

export interface SignupRequest {
  email: string;
  password: string;
  name: string;
}

export interface LoginRequest {
  email: string;
  password: string;
}

export type RefreshState = 'success' | 'error' | null;

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  private readonly API_URL = '/api';
  private readonly USER_KEY = 'auth_user';

  private readonly http = inject(HttpClient);
  private readonly router = inject(Router);
  private readonly platformId = inject(PLATFORM_ID);
  // SSR Context
  private readonly request = inject('REQUEST' as any, { optional: true });

  private currentUserSubject = new BehaviorSubject<User | null>(null);
  public currentUser$ = this.currentUserSubject.asObservable();

  public isRefreshing = false;
  public refreshTokenSubject = new BehaviorSubject<RefreshState>(null);

  constructor() {
    this.restoreSession();
  }

  private restoreSession() {
    try {
      let storedUser: string | null = null;

      if (isPlatformBrowser(this.platformId)) {
        storedUser = this.getCookie(this.USER_KEY);
      } else if (this.request) {
        // SSR context: read from request headers
        const req = this.request as any;
        const cookieHeader = req.headers?.get?.('cookie') || req.headers?.cookie;
        if (cookieHeader) {
          storedUser = this.parseCookieHeader(cookieHeader, this.USER_KEY);
        }
      }

      if (storedUser && storedUser !== 'undefined') {
        this.currentUserSubject.next(JSON.parse(decodeURIComponent(storedUser)));
      } else {
        this.clearAuth();
      }
    } catch (e) {
      console.error('Error restoring session', e);
      this.clearAuth();
    }
  }

  signup(data: SignupRequest): Observable<AuthResponse> {
    return this.http
      .post<AuthResponse>(`${this.API_URL}/auth/signup`, data)
      .pipe(tap((response) => this.handleAuthResponse(response)));
  }

  login(data: LoginRequest): Observable<AuthResponse> {
    return this.http
      .post<AuthResponse>(`${this.API_URL}/auth/login`, data)
      .pipe(tap((response) => this.handleAuthResponse(response)));
  }

  logout(): void {
    // サーバーサイドの Cookie (HttpOnly) も削除するために必要
    this.http.post(`${this.API_URL}/auth/logout`, {}).subscribe({
      next: () => this.handleLogoutSuccess(),
      error: () => this.handleLogoutSuccess(), // エラーでもフロント側はクリアする
    });
  }

  private handleLogoutSuccess(): void {
    this.clearAuth();
    this.router.navigate(['/login']);
  }

  private handleAuthResponse(response: AuthResponse) {
    // auth_token は HttpOnly Cookie としてサーバーから設定されるため、
    // ここで保存する必要はなくなりました。
    this.saveUser(response.user);
    this.currentUserSubject.next(response.user);
  }

  private saveUser(user: User): void {
    if (isPlatformBrowser(this.platformId) && user) {
      this.setCookie(this.USER_KEY, JSON.stringify(user), 7);
    }
  }

  private setCookie(name: string, value: string, days: number): void {
    if (isPlatformBrowser(this.platformId)) {
      const date = new Date();
      date.setTime(date.getTime() + days * 24 * 60 * 60 * 1000);
      const expires = '; expires=' + date.toUTCString();
      document.cookie = name + '=' + encodeURIComponent(value) + expires + '; path=/; SameSite=Lax';
    }
  }

  private getCookie(name: string): string | null {
    if (isPlatformBrowser(this.platformId)) {
      const nameEQ = name + '=';
      const ca = document.cookie.split(';');
      for (let i = 0; i < ca.length; i++) {
        let c = ca[i];
        while (c.charAt(0) === ' ') c = c.substring(1, c.length);
        if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length, c.length);
      }
    }
    return null;
  }

  private parseCookieHeader(header: string, name: string): string | null {
    const nameEQ = name + '=';
    const ca = header.split(';');
    for (let i = 0; i < ca.length; i++) {
      let c = ca[i];
      while (c.charAt(0) === ' ') c = c.substring(1, c.length);
      if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length, c.length);
    }
    return null;
  }

  clearAuth(): void {
    if (isPlatformBrowser(this.platformId)) {
      // HttpOnly 属性ではないものを削除する
      // (auth_token などの HttpOnly Cookie は JS から削除できないため、サーバー側でクリアする必要がある)
      this.setCookie(this.USER_KEY, '', -1);
    }
    this.currentUserSubject.next(null);
  }

  isLoggedIn(): boolean {
    return !!this.currentUserValue;
  }

  get currentUserValue(): User | null {
    return this.currentUserSubject.value;
  }

  changePassword(data: { currentPassword: string; newPassword: string }): Observable<void> {
    return this.http.put<void>(`${this.API_URL}/auth/password`, data);
  }

  withdraw(): Observable<void> {
    return this.http.delete<void>(`${this.API_URL}/auth/withdraw`).pipe(
      tap(() => {
        this.clearAuth();
        this.router.navigate(['/login']);
      }),
    );
  }

  requestPasswordReset(email: string): Observable<MessageResponse> {
    return this.http.post<MessageResponse>(`${this.API_URL}/auth/password-reset/request`, {
      email,
    });
  }

  resetPassword(token: string, newPassword: string): Observable<MessageResponse> {
    return this.http.post<MessageResponse>(`${this.API_URL}/auth/password-reset`, {
      token,
      newPassword,
    });
  }

  refresh(): Observable<AuthResponse> {
    return this.http
      .post<AuthResponse>(`${this.API_URL}/auth/refresh`, {})
      .pipe(tap((response) => this.handleAuthResponse(response)));
  }
}

export interface MessageResponse {
  message: string;
}

import { inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, switchMap, from } from 'rxjs';

export interface Recipe {
  id: number;
  userId: number;
  name: string;
  url: string;
  memo: string;
  createdAt: string;
  updatedAt: string;
  tags?: Tag[];
  images?: RecipeImage[];
}

export interface Tag {
  id: number;
  name: string;
}

export interface RecipeImage {
  id: number;
  recipeId: number;
  imageUrl: string;
  createdAt: string;
}

export interface CreateRecipeRequest {
  name: string;
  url: string;
  memo: string;
  tagIds: number[];
}

export interface UpdateRecipeRequest {
  name: string;
  url: string;
  memo: string;
}

export interface SearchRecipeRequest {
  query: string;
  tagIds: number[];
}

export interface CreateRecipeImageRequest {
  filename: string;
  contentType: string;
  size: number;
}

export interface CreateRecipeImageResponse {
  image: RecipeImage;
  uploadUrl: string;
}

@Injectable({
  providedIn: 'root',
})
export class RecipeService {
  private readonly API_URL = '/api/recipes';
  private readonly TAG_API_URL = '/api/tags';
  private readonly http = inject(HttpClient);

  createRecipe(data: CreateRecipeRequest): Observable<Recipe> {
    return this.http.post<Recipe>(this.API_URL, data);
  }

  getRecipe(id: number): Observable<Recipe> {
    return this.http.get<Recipe>(`${this.API_URL}/${id}`);
  }

  getUserRecipes(): Observable<Recipe[]> {
    return this.http.get<Recipe[]>(this.API_URL);
  }

  searchRecipes(data: SearchRecipeRequest): Observable<Recipe[]> {
    return this.http.post<Recipe[]>(`${this.API_URL}/search`, data);
  }

  updateRecipe(id: number, data: UpdateRecipeRequest): Observable<Recipe> {
    return this.http.put<Recipe>(`${this.API_URL}/${id}`, data);
  }

  deleteRecipe(id: number): Observable<void> {
    return this.http.delete<void>(`${this.API_URL}/${id}`);
  }

  addTags(recipeId: number, tagIds: number[]): Observable<void> {
    return this.http.post<void>(`${this.API_URL}/${recipeId}/tags`, { tagIds });
  }

  removeTags(recipeId: number, tagIds: number[]): Observable<void> {
    return this.http.request<void>('delete', `${this.API_URL}/${recipeId}/tags`, {
      body: { tagIds },
    });
  }

  uploadImage(recipeId: number, file: File): Observable<RecipeImage> {
    const body: CreateRecipeImageRequest = {
      filename: file.name,
      contentType: file.type,
      size: file.size,
    };

    return this.http
      .post<CreateRecipeImageResponse>(`${this.API_URL}/${recipeId}/images`, body)
      .pipe(
        switchMap((res) => {
          const uploadUrl = res.uploadUrl;
          return from(
            fetch(uploadUrl, {
              method: 'PUT',
              headers: { 'Content-Type': file.type },
              body: file,
            }).then((r) => {
              if (!r.ok) throw new Error(`S3 upload failed: ${r.status}`);
              return res.image;
            }),
          );
        }),
      );
  }

  // Tag management
  createTag(name: string): Observable<Tag> {
    return this.http.post<Tag>(this.TAG_API_URL, { name });
  }

  getAllTags(): Observable<Tag[]> {
    return this.http.get<Tag[]>(this.TAG_API_URL);
  }

  deleteTag(id: number): Observable<void> {
    return this.http.delete<void>(`${this.TAG_API_URL}/${id}`);
  }
}

import {
  Component,
  EventEmitter,
  inject,
  Input,
  OnChanges,
  OnInit,
  Output,
  SimpleChanges,
} from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { MatCardModule } from '@angular/material/card';
import { MatIconModule } from '@angular/material/icon';
import { TranslocoPipe, TranslocoService } from '@jsverse/transloco';
import { RecipeService, Tag } from '../../../../core/services/recipe.service';
import { TagSelectComponent } from '../../molecules/tag-select/tag-select.component';
import { ButtonComponent } from '../../atoms/button/button.component';
import { HeadlineComponent } from '../../atoms/headline/headline.component';
import { InputComponent } from '../../atoms/input/input.component';
import { TextareaComponent } from '../../atoms/textarea/textarea.component';
import { VALIDATION_RULES } from '../../../../core/constants/validation.constants';

export interface RecipeFormData {
  name: string;
  url: string;
  memo: string;
  tagIds: number[];
}

export interface RecipeFormSubmitEvent {
  formData: RecipeFormData;
  file: File | null;
}

@Component({
  selector: 'app-recipe-form',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    RouterModule,
    MatCardModule,
    MatIconModule,
    TranslocoPipe,
    TagSelectComponent,
    ButtonComponent,
    HeadlineComponent,
    InputComponent,
    TextareaComponent,
  ],
  templateUrl: './recipe-form.component.html',
  styleUrl: './recipe-form.component.scss',
})
export class RecipeFormComponent implements OnInit, OnChanges {
  private readonly fb = inject(FormBuilder);
  private readonly recipeService = inject(RecipeService);
  private readonly translate = inject(TranslocoService);

  @Input() titleKey: string = 'FEATURES.RECIPES.RECIPE_CREATE.TITLE';
  @Input() submitLabelKey: string = 'COMPONENTS.ORGANISMS.RECIPE_FORM.SAVE';
  @Input() submittingLabelKey: string = 'COMPONENTS.ORGANISMS.RECIPE_FORM.SAVING';

  @Input() isSubmitting = false;
  @Input() initialData: Partial<RecipeFormData> = {};
  @Input() initialImagePreview: string | null = null;

  @Output() save = new EventEmitter<RecipeFormSubmitEvent>();

  recipeForm: FormGroup;
  tags: Tag[] = [];
  fieldErrors: Record<string, string[]> = {};
  selectedFile: File | null = null;
  imagePreview: string | null = null;
  imageError: string | null = null;
  isDragover = false;

  protected readonly VALIDATION_RULES = VALIDATION_RULES;

  constructor() {
    this.recipeForm = this.fb.group({
      name: [
        '',
        [Validators.required, Validators.maxLength(VALIDATION_RULES.RECIPE.NAME_MAX_LENGTH)],
      ],
      url: [
        '',
        [
          Validators.required,
          Validators.pattern(/^https?:\/\/[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}.*|^https?:\/\/localhost.*/),
        ],
      ],
      memo: ['', Validators.maxLength(VALIDATION_RULES.RECIPE.MEMO_MAX_LENGTH)],
      tagIds: [[]],
    });
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['initialData'] && this.initialData) {
      this.recipeForm.patchValue({
        name: this.initialData.name || '',
        url: this.initialData.url || '',
        memo: this.initialData.memo || '',
        tagIds: this.initialData.tagIds || [],
      });
    }
    if (changes['initialImagePreview'] && this.initialImagePreview) {
      this.imagePreview = this.initialImagePreview;
    }
  }

  onUrlBlur() {
    const urlControl = this.recipeForm.get('url');
    if (urlControl?.value) {
      let url = urlControl.value.trim();
      if (url && !url.includes('://')) {
        url = 'https://' + url;
        urlControl.setValue(url);
      }
    }
  }

  ngOnInit() {
    this.recipeService.getAllTags().subscribe({
      next: (tags) => (this.tags = tags),
      error: (err) => console.error('Failed to load tags', err),
    });
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files?.[0]) {
      this.handleFile(input.files[0]);
    }
  }

  onDragOver(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragover = true;
  }

  onDragLeave(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragover = false;
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragover = false;
    if (event.dataTransfer?.files?.[0]) {
      this.handleFile(event.dataTransfer.files[0]);
    }
  }

  removeImage(event: Event) {
    event.stopPropagation();
    this.selectedFile = null;
    this.imagePreview = null;
    this.imageError = null;
  }

  private handleFile(file: File) {
    this.imageError = null;

    if (!(VALIDATION_RULES.IMAGE.ALLOWED_TYPES as readonly string[]).includes(file.type)) {
      this.imageError = 'JPEG, PNG, WebP のみアップロードできます';
      return;
    }

    if (file.size > VALIDATION_RULES.IMAGE.MAX_FILE_SIZE) {
      this.imageError = 'ファイルサイズは50MB以下にしてください';
      return;
    }

    this.selectedFile = file;

    const reader = new FileReader();
    reader.onload = (e) => {
      this.imagePreview = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  }

  onSubmit() {
    this.fieldErrors = {};
    if (this.recipeForm.valid) {
      this.save.emit({
        formData: this.recipeForm.value as RecipeFormData,
        file: this.selectedFile,
      });
    }
  }

  handleServerErrors(err: any): boolean {
    let hasValidationErrors = false;
    if (err.error?.error?.details) {
      const details = err.error.error.details;
      Object.keys(details).forEach((field) => {
        hasValidationErrors = true;
        const messages = (details as any)[field].map((d: any) => {
          switch (d.code) {
            case 'REQUIRED':
              return this.translate.translate('VALIDATION.REQUIRED');
            case 'TEXT_TOO_LONG':
              return this.translate.translate('VALIDATION.MAX_LENGTH', { max: d.params?.max });
            case 'URL_INVALID_FORMAT':
              return this.translate.translate('VALIDATION.INVALID_URL');
            default:
              return this.translate.translate('VALIDATION.INVALID_INPUT');
          }
        });
        this.fieldErrors[field] = messages;
      });
    }
    return hasValidationErrors;
  }
}

