  name: string;
}

export interface RecipeImage {
  id: number;
  recipeId: number;
  imageUrl: string;
  createdAt: string;
}

export interface CreateRecipeRequest {
  name: string;
  url: string;
  memo: string;
  tagIds: number[];
}

export interface UpdateRecipeRequest {
  name: string;
  url: string;
  memo: string;
}

export interface SearchRecipeRequest {
  query: string;
