import {
  Component,
  EventEmitter,
  inject,
  Input,
  OnChanges,
  OnInit,
  Output,
  SimpleChanges,
} from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { MatCardModule } from '@angular/material/card';
import { MatIconModule } from '@angular/material/icon';
import { TranslocoPipe, TranslocoService } from '@jsverse/transloco';
import { RecipeService, Tag } from '../../../../core/services/recipe.service';
import { TagSelectComponent } from '../../molecules/tag-select/tag-select.component';
import { ButtonComponent } from '../../atoms/button/button.component';
import { HeadlineComponent } from '../../atoms/headline/headline.component';
import { InputComponent } from '../../atoms/input/input.component';
import { TextareaComponent } from '../../atoms/textarea/textarea.component';
import { VALIDATION_RULES } from '../../../../core/constants/validation.constants';

export interface RecipeFormData {
  name: string;
  url: string;
  memo: string;
  tagIds: number[];
}

export interface RecipeFormSubmitEvent {
  formData: RecipeFormData;
  file: File | null;
}

@Component({
  selector: 'app-recipe-form',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    RouterModule,
    MatCardModule,
    MatIconModule,
    TranslocoPipe,
    TagSelectComponent,
    ButtonComponent,
    HeadlineComponent,
    InputComponent,
    TextareaComponent,
  ],
  templateUrl: './recipe-form.component.html',
  styleUrl: './recipe-form.component.scss',
})
export class RecipeFormComponent implements OnInit, OnChanges {
  private readonly fb = inject(FormBuilder);
  private readonly recipeService = inject(RecipeService);
  private readonly translate = inject(TranslocoService);

  @Input() titleKey: string = 'FEATURES.RECIPES.RECIPE_CREATE.TITLE';
  @Input() submitLabelKey: string = 'COMPONENTS.ORGANISMS.RECIPE_FORM.SAVE';
  @Input() submittingLabelKey: string = 'COMPONENTS.ORGANISMS.RECIPE_FORM.SAVING';

  @Input() isSubmitting = false;
  @Input() initialData: Partial<RecipeFormData> = {};
  @Input() initialImagePreview: string | null = null;

  @Output() save = new EventEmitter<RecipeFormSubmitEvent>();

  recipeForm: FormGroup;
  tags: Tag[] = [];
  fieldErrors: Record<string, string[]> = {};
  selectedFile: File | null = null;
  imagePreview: string | null = null;
  imageError: string | null = null;
  isDragover = false;

  protected readonly VALIDATION_RULES = VALIDATION_RULES;

  constructor() {
    this.recipeForm = this.fb.group({
      name: [
        '',
        [Validators.required, Validators.maxLength(VALIDATION_RULES.RECIPE.NAME_MAX_LENGTH)],
      ],
      url: [
        '',
        [
          Validators.required,
          Validators.pattern(/^https?:\/\/[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}.*|^https?:\/\/localhost.*/),
        ],
      ],
      memo: ['', Validators.maxLength(VALIDATION_RULES.RECIPE.MEMO_MAX_LENGTH)],
      tagIds: [[]],
    });
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['initialData'] && this.initialData) {
      this.recipeForm.patchValue({
        name: this.initialData.name || '',
        url: this.initialData.url || '',
        memo: this.initialData.memo || '',
        tagIds: this.initialData.tagIds || [],
      });
    }
    if (changes['initialImagePreview'] && this.initialImagePreview) {
      this.imagePreview = this.initialImagePreview;
    }
  }

  onUrlBlur() {
    const urlControl = this.recipeForm.get('url');
    if (urlControl?.value) {
      let url = urlControl.value.trim();
      if (url && !url.includes('://')) {
        url = 'https://' + url;
        urlControl.setValue(url);
      }
    }
  }

  ngOnInit() {
    this.recipeService.getAllTags().subscribe({
      next: (tags) => (this.tags = tags),
      error: (err) => console.error('Failed to load tags', err),
    });
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files?.[0]) {
      this.handleFile(input.files[0]);
    }
  }

  onDragOver(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragover = true;
  }

  onDragLeave(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragover = false;
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    this.isDragover = false;
    if (event.dataTransfer?.files?.[0]) {
      this.handleFile(event.dataTransfer.files[0]);
    }
  }

  removeImage(event: Event) {
    event.stopPropagation();
    this.selectedFile = null;
    this.imagePreview = null;
    this.imageError = null;
  }

  private handleFile(file: File) {
    this.imageError = null;

    if (!(VALIDATION_RULES.IMAGE.ALLOWED_TYPES as readonly string[]).includes(file.type)) {
      this.imageError = 'JPEG, PNG, WebP のみアップロードできます';
      return;
    }

    if (file.size > VALIDATION_RULES.IMAGE.MAX_FILE_SIZE) {
      this.imageError = 'ファイルサイズは50MB以下にしてください';
      return;
    }

    this.selectedFile = file;

    const reader = new FileReader();
    reader.onload = (e) => {
      this.imagePreview = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  }

  onSubmit() {
    this.fieldErrors = {};
    if (this.recipeForm.valid) {
      this.save.emit({
        formData: this.recipeForm.value as RecipeFormData,
        file: this.selectedFile,
      });
    }
  }

  handleServerErrors(err: any): boolean {
    let hasValidationErrors = false;
    if (err.error?.error?.details) {
      const details = err.error.error.details;
      Object.keys(details).forEach((field) => {
        hasValidationErrors = true;
        const messages = (details as any)[field].map((d: any) => {
          switch (d.code) {
            case 'REQUIRED':
              return this.translate.translate('VALIDATION.REQUIRED');
            case 'TEXT_TOO_LONG':
              return this.translate.translate('VALIDATION.MAX_LENGTH', { max: d.params?.max });
            case 'URL_INVALID_FORMAT':
              return this.translate.translate('VALIDATION.INVALID_URL');
            default:
              return this.translate.translate('VALIDATION.INVALID_INPUT');
          }
        });
        this.fieldErrors[field] = messages;
      });
    }
    return hasValidationErrors;
  }
}

import { Component, inject, OnInit, ElementRef, ViewChild } from '@angular/core';
import { RouterModule } from '@angular/router';
import { FormsModule, ReactiveFormsModule, FormControl } from '@angular/forms';
import { CommonModule, AsyncPipe } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { SearchModeToggleComponent } from '../../shared/components/molecules/search-mode-toggle/search-mode-toggle.component';
import { MatChipsModule } from '@angular/material/chips';
import {
  MatAutocompleteModule,
  MatAutocompleteSelectedEvent,
} from '@angular/material/autocomplete';
import { MatFormFieldModule } from '@angular/material/form-field';
import { TranslocoPipe } from '@jsverse/transloco';
import { Observable, startWith, map } from 'rxjs';
import { COMMA, ENTER } from '@angular/cdk/keycodes';

import { RecipeService, Recipe, Tag } from '../../core/services/recipe.service';
import { RecipeCardComponent } from '../../shared/components/organisms/recipe-card/recipe-card.component';
import { HeadlineComponent } from '../../shared/components/atoms/headline/headline.component';
import { ButtonComponent } from '../../shared/components/atoms/button/button.component';
import { InputComponent } from '../../shared/components/atoms/input/input.component';
import { SearchBarComponent } from '../../shared/components/molecules/search-bar/search-bar.component';
import { EmptyStateComponent } from '../../shared/components/molecules/empty-state/empty-state.component';

@Component({
  selector: 'app-recipes',
  standalone: true,
  imports: [
    CommonModule,
    RouterModule,
    FormsModule,
    ReactiveFormsModule,
    MatIconModule,
    SearchModeToggleComponent,
    MatChipsModule,
    MatAutocompleteModule,
    MatFormFieldModule,
    TranslocoPipe,
    AsyncPipe,
    RecipeCardComponent,
    HeadlineComponent,
    ButtonComponent,
    InputComponent,
    SearchBarComponent,
    EmptyStateComponent,
  ],
  templateUrl: './recipes.component.html',
  styleUrl: './recipes.component.scss',
})
export class RecipesComponent implements OnInit {
  private readonly recipeService = inject(RecipeService);

  recipes: Recipe[] = [];
  availableTags: Tag[] = [];
  searchQuery = '';
  selectedTagIds: number[] = [];

  // Search Mode
  searchMode: 'keyword' | 'tag' = 'keyword';

  // Tag Chips Logic
  separatorKeysCodes: number[] = [ENTER, COMMA];
  tagCtrl = new FormControl('');
  filteredTags: Observable<Tag[]>;
  @ViewChild('tagInput') tagInput!: ElementRef<HTMLInputElement>;

  constructor() {
    this.filteredTags = this.tagCtrl.valueChanges.pipe(
      startWith(null),
      map((tag: string | null | Tag) => {
        // Handle both string input and Tag object selection
        const filterValue = typeof tag === 'string' ? tag : tag?.name || '';
        return filterValue ? this.filterTags(filterValue) : this.getUnselectedTags();
      }),
    );
  }

  ngOnInit() {
    this.loadRecipes();
    this.loadTags();
  }

  loadRecipes() {
    this.recipeService.getUserRecipes().subscribe({
      next: (recipes) => (this.recipes = recipes),
      error: (err: Error) => console.error('Failed to load recipes', err),
    });
  }

  loadTags() {
    this.recipeService.getAllTags().subscribe({
      next: (tags) => (this.availableTags = tags),
      error: (err: Error) => console.error('Failed to load tags', err),
    });
  }

  search() {
    const query = this.searchMode === 'keyword' ? this.searchQuery : '';
    const tagIds = this.searchMode === 'tag' ? this.selectedTagIds : [];

    this.recipeService
      .searchRecipes({
        query: query || '',
        tagIds: tagIds,
      })
      .subscribe({
        next: (recipes) => (this.recipes = recipes),
        error: (err: Error) => console.error('Failed to search recipes', err),
      });
  }

  onDeleteRecipe(id: number): void {
    this.recipeService.deleteRecipe(id).subscribe({
      next: () => {
        this.recipes = this.recipes.filter((r) => r.id !== id);
      },
      error: (err: Error) => console.error('Failed to delete recipe', err),
    });
  }

  // --- Tag Logic ---

  appendTag(event: any): void {
    const value = (event.value || '').trim();

    // If matches an existing tag, select it
    if (value) {
      const existingTag = this.availableTags.find(
        (tag) => tag.name.toLowerCase() === value.toLowerCase(),
      );

      if (existingTag && !this.selectedTagIds.includes(existingTag.id)) {
        this.selectedTagIds.push(existingTag.id);
      }
    }

    // Always clear input
    if (event.chipInput) {
      event.chipInput.clear();
    }
    this.tagCtrl.setValue(null);
  }

  removeTag(tagId: number): void {
    const index = this.selectedTagIds.indexOf(tagId);
    if (index >= 0) {
      this.selectedTagIds.splice(index, 1);
    }
  }

  selectedTag(event: MatAutocompleteSelectedEvent): void {
    const tag: Tag = event.option.value;
    if (!this.selectedTagIds.includes(tag.id)) {
      this.selectedTagIds.push(tag.id);
    }
    this.tagInput.nativeElement.value = '';
    this.tagCtrl.setValue(null);
  }

  getTagName(id: number): string {
    return this.availableTags.find((t) => t.id === id)?.name || '';
  }

  private filterTags(value: string): Tag[] {
    const filterValue = value.toLowerCase();
    return this.availableTags.filter(
      (tag) =>
        tag.name.toLowerCase().includes(filterValue) && !this.selectedTagIds.includes(tag.id),
    );
  }

  private getUnselectedTags(): Tag[] {
    return this.availableTags.filter((tag) => !this.selectedTagIds.includes(tag.id));
  }
}

