(_route, _state) => {
  const platformId = inject(PLATFORM_ID);

  // SSR ではブラウザ Cookie を参照できないため、ガードを素通りさせる
  // クライアントのハイドレーション後に再評価される
  if (!isPlatformBrowser(platformId)) {
    return true;
  }

  const authService = inject(AuthService);
  const router = inject(Router);

  if (authService.isLoggedIn()) {
    return true;
  }

  router.navigate(['/login']);
  return false;
}

src/app/core/interceptors/auth.intercept.defaultValue:
(
  req: HttpRequest<any>,
  next: HttpHandlerFn,
  authService: AuthService,
): Observable<HttpEvent<any>> => {
  return next(req).pipe(
    catchError((error) => {
      if (error instanceof HttpErrorResponse && error.status === 401) {
        // ログインやリフレッシュ自体の失敗はそのままエラーとして流す
        if (req.url.includes('/auth/login') || req.url.includes('/auth/refresh')) {
          authService.clearAuth();
          return throwError(() => error);
        }

        return handleUnauthorizedError(authService, req, next);
      }
      return throwError(() => error);
    }),
  );
}

(
  authService: AuthService,
  req: HttpRequest<any>,
  next: HttpHandlerFn,
): Observable<HttpEvent<any>> => {
  if (!authService.isRefreshing) {
    authService.isRefreshing = true;
    authService.refreshTokenSubject.next(null);

    return authService.refresh().pipe(
      switchMap(() => {
        authService.isRefreshing = false;
        authService.refreshTokenSubject.next('success'); // 成功を通知
        return next(req);
      }),
      catchError((err) => {
        authService.isRefreshing = false;
        authService.refreshTokenSubject.next('error'); // 待機中の他リクエストに失敗を通知
        authService.clearAuth();
        return throwError(() => err);
      }),
    );
  } else {
    // すでにリフレッシュ中の場合は、信号を待ってから再試行
    return authService.refreshTokenSubject.pipe(
      filter((token) => token !== null),
      take(1),
      switchMap((token) => {
        if (token === 'error') {
          return throwError(
            () => new HttpErrorResponse({ status: 401, statusText: 'Unauthorized' }),
          );
        }
        return next(req);
      }),
    );
  }
}

src/app/core/interceptors/case-converter.defaultValue:
(req, next) => {
  if (!isApiRequest(req.url)) {
    return next(req);
  }

  let modifiedReq: HttpRequest<any> = req;

  if (req.body && !(req.body instanceof FormData) && !(req.body instanceof Blob)) {
    try {
      modifiedReq = req.clone({
        body: decamelizeKeys(req.body, { deep: true }),
      });
    } catch (e) {
      console.error('Error converting request body keys to snake_case', e);
    }
  }

  return next(modifiedReq).pipe(
    map((event) => {
      if (
        event instanceof HttpResponse &&
        event.body &&
        typeof event.body === 'object' &&
        !(event.body instanceof Blob)
      ) {
        try {
          const camelCaseBody = camelcaseKeys(event.body, { deep: true });
          return event.clone({ body: camelCaseBody });
        } catch (e) {
          console.error('Error converting response body keys to camelCase', e);
        }
      }
      return event;
    }),
  );
}

